def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    # Regex to find tags of form "# <TAG>" or "# TAG:" or "# TAG"
    tag_pattern = re.compile(r'#\s*(?:<(?P<tag1>\w+)>|(?P<tag2>\w+)\s*:?)')

    tags: Set[str] = set()
    in_code: bool = False
    # Preserve line endings
    lines = text.splitlines(True)
    new_lines: List[str] = []

    for line in lines:
        # Toggle code block state when encountering a line that starts an entry
        if line.lstrip().startswith('```'):
            in_code = not in_code
            new_lines.append(line)
            continue

        # If we are not inside a code block, find tags
        if not in_code:
            for m in tag_pattern.finditer(line):
                tag = m.group('tag1') or m.group('tag2')
                if tag:
                    tags.add(tag)

        # If a replacer is provided, replace tags accordingly
        if replacer is not None:
            def repl_func(match):
                tag = match.group('tag1') or match.group('tag2')
                if tag is None:
                    return match.group(0)
                try:
                    new_tag = str(replacer(tag))
                except Exception:
                    new_tag = tag
                return '# ' + new_tag

            line = tag_pattern.sub(repl_func, line)

        new_lines.append(line)

    return tags, ''.join(new_lines)

